class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    packed = @packer ? @packer.dump({ payload: payload, stale: stale }) : { payload: payload, stale: stale }
    @store[key] = packed
  end

  def read(key)
    return nil unless @store.key?(key)
    unpacked = @packer ? @packer.load(@store[key]) : @store[key]
    unpacked[:payload]
  end

  def sweep
    @store.keys.each do |key|
      unpacked = @packer ? @packer.load(@store[key]) : @store[key]
      if unpacked[:stale]
        @store.delete(key)
      end
    end
  end
end
