class OpenRecord
  def initialize(**attrs)
    @__attributes__ = {}
    attrs.each { |key, value| @__attributes__[key.to_s] = value }
  end

  def respond_to?(method_name, include_all = false)
    name = method_name.to_s
    return true if @__attributes__.key?(name)
    return true if @__attributes__.key?(name.chomp('='))
    super
  end

  def respond_to_missing?(method_name, include_all = false)
    name = method_name.to_s
    return true if @__attributes__.key?(name)
    return true if @__attributes__.key?(name.chomp('='))
    super
  end

  def method_missing(name, *args)
    key = name.to_s
    if key.end_with?('=')
      @__attributes__[key.chop] = args.first
      args.first
    else
      raise NoMethodError, "undefined method #{name.inspect} for #{self.inspect}"
    end
  end

  def respond_to?(method_name, include_all = false)
    name = method_name.to_s
    return true if @__attributes__.key?(name)
    return true if @__attributes__.key?(name.chomp('='))
    super
  end
end
